with filtered as (select id, name, email, city, is_active, credit_limit, age, upper(trim(email)) as email_normalized, coalesce(segment, 'NONE') as resolved_segment from customers where segment is distinct from 'Consumer' and city is not null) select id, email, city, credit_limit, resolved_segment from filtered qualify row_number() over (partition by city order by age desc, id) = 1;
